	/*         margin-left: calc(var(--ytd-rich-grid-item-margin)/2 + var(--ytd-rich-grid-gutter-margin)); */
	    }
	}

	@media (min-width: 1800px) {
	    #contents {
	        --ytd-rich-grid-items-per-row: 5;
	        --ytd-rich-grid-posts-per-row: 5;
	    }
	    #dismissible #contents {
	        --ytd-rich-grid-items-per-row: 6;
	    }

	    #contents ytd-rich-item-renderer:nth-of-type(5n-4) {
	/*         margin-left: calc(var(--ytd-rich-grid-item-margin)/2 + var(--ytd-rich-grid-gutter-margin)); */
	    }
	}

	@media (min-width: 2200px) {
	    #contents {
	        --ytd-rich-grid-items-per-row: 6;
	        --ytd-rich-grid-posts-per-row: 6;
