	    #contents ytd-rich-item-renderer:nth-of-type(6n-5) {
	/*         margin-left: calc(var(--ytd-rich-grid-item-margin)/2 + var(--ytd-rich-grid-gutter-margin)); */
	    }
	}

	ytd-subscribe-button-renderer yt-smartimation,
	a[href*="https://support.google.com/youtube?p=ppp"],
	.ytm-paid-content-overlay-renderer.YtmPaidContentOverlayHost,
	.ytm-paid-content-overlay-renderer,
	.YtmPaidContentOverlayHost {
	    display: none;
	}

	#content {
	    &:has(#frosted-glass.with-chipbar) {
	        &:has(#chips-wrapper) {
	            #primary #header {
	                height: 40px;
	            }
	        }
	        &:has(#selected-chip-content) {
	            #primary #header {
	                height: var(--ytd-chips-bar-dynamic-height);
	            }
	        }
	        &:not(:has(#chips-wrapper)) #frosted-glass.with-chipbar {
	            /* display: none !important;*/
	            max-height: 60px;
	        }
	    }
	    &:has(#frosted-glass.without-chipbar) {
	        #contents.ytd-rich-grid-renderer {
	            padding-top: 2rem;
	        }
	    }
	}
}

@-moz-document regexp("^https://www.youtube.com/(\\?bp=.+)?$") {
	:is(#big-yoodle, ytd-rich-section-renderer, ytd-brand-video-shelf-renderer):has(#dismissible),
	#contents ytd-rich-section-renderer {
	    display: none;
	}
}
